import torch.nn as nn
from torch.utils.cpp_extension import load_inline

matmul_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Tile size for shared memory
#define TILE_SIZE 32

// Register blocking factors
#define BLOCK_ROWS 4
#define BLOCK_COLS 4

__global__ void matmul_kernel_register_blocking(const float* A, const float* B, float* C, int N) {
    // Shared memory for tiles of A and B
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int globalRow = blockIdx.y * TILE_SIZE + threadIdx.y;
    int globalCol = blockIdx.x * TILE_SIZE + threadIdx.x;

    float Csub[BLOCK_ROWS][BLOCK_COLS] = {0.0f};

    // Loop over tiles
    for (int tile = 0; tile < (N + TILE_SIZE - 1) / TILE_SIZE; ++tile) {
        // Load tiles into shared memory
        // Each thread loads one element of A and one element of B
        int a_row = blockIdx.y * TILE_SIZE + threadIdx.y;
        int a_col = tile * TILE_SIZE + threadIdx.x;
        if (a_row < N && a_col < N) {
            As[threadIdx.y][threadIdx.x] = A[a_row * N + a_col];
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0f; // Pad with zeros
        }

        int b_row = tile * TILE_SIZE + threadIdx.y;
        int b_col = blockIdx.x * TILE_SIZE + threadIdx.x;
        if (b_row < N && b_col < N) {
            Bs[threadIdx.y][threadIdx.x] = B[b_row * N + b_col];
        } else {
            Bs[threadIdx.y][threadIdx.x] = 0.0f; // Pad with zeros
        }

        __syncthreads();

        // Perform dot product on shared memory tiles using register blocking
        for (int k = 0; k < TILE_SIZE; ++k) {
            for (int r = 0; r < BLOCK_ROWS; ++r) {
                for (int c = 0; c < BLOCK_COLS; ++c) {
                    if ((globalRow + r) < N && (globalCol + c) < N) {
                        Csub[r][c] += As[threadIdx.y + r][k] * Bs[k][threadIdx.x + c];
                    }
                }
            }
        }
        __syncthreads();
    }

    // Write results from registers to global memory
    for (int r = 0; r < BLOCK_ROWS; ++r) {
        for (int c = 0; c < BLOCK_COLS; ++c) {
            if ((globalRow + r) < N && (globalCol + c) < N) {
                C[(globalRow + r) * N + (globalCol + c)] = Csub[r][c];
            }
        }
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    const int block_size = TILE_SIZE;
    dim3 dimBlock(block_size, block_size);
    dim3 dimGrid((N + dimBlock.x - 1) / dimBlock.x, (N + dimBlock.y - 1) / dimBlock.y);

    matmul_kernel_register_blocking<<<dimGrid, dimBlock>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

matmul_cpp_source = (
    "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"
)

matmul_module = load_inline(
    name="matmul_module",
    cpp_sources=matmul_cpp_source,
    cuda_sources=matmul_cuda_source,
    functions=["matmul_cuda"],
    verbose=True,
    extra_cflags=["-O3"],
    extra_ldflags=[""],
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.matmul_cuda = matmul_module

    def forward(self, A, B):
        return self.matmul_cuda.matmul_cuda(A, B)
"}

